mapper.select:
SELECT 
    TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24:MI:SS') as time,
    DENSITY as value
FROM CLOUDWALK.CROWD_STATISTICS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY RECORD_TIME

SELECT 
    TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24:MI:SS') as time,
    COUNT as value
FROM CLOUDWALK.CROWD_STATISTICS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY RECORD_TIME

SELECT 
    TO_CHAR(RECORD_TIME, 'HH24') as hour,
    ROUND(AVG(DENSITY), 2) as avgDensity,
    MAX(DENSITY) as maxDensity,
    COUNT(*) as count
FROM CLOUDWALK.CROWD_STATISTICS
WHERE DENSITY >= #{threshold}

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
GROUP BY TO_CHAR(RECORD_TIME, 'HH24')
ORDER BY hour

SELECT 
FROM CLOUDWALK.CROWD_STATISTICS


        AND DEVICE_CODE = #{params.deviceCode}


        AND DEVICE_NAME LIKE '%' || #{params.deviceName} || '%'


        AND TOURISM_NAME = #{params.tourismName}


        AND ALG_NAME = #{params.algName}


        AND DENSITY >= #{params.minDensity}


        AND DENSITY <= #{params.maxDensity}


        AND RECORD_TIME >= #{params.startTime}


        AND RECORD_TIME <= #{params.endTime}


ORDER BY RECORD_TIME DESC
OFFSET #{params.offset} ROWS FETCH NEXT #{params.limit} ROWS ONLY

SELECT COUNT(*)
FROM CLOUDWALK.CROWD_STATISTICS


        AND DEVICE_CODE = #{params.deviceCode}


        AND DEVICE_NAME LIKE '%' || #{params.deviceName} || '%'


        AND TOURISM_NAME = #{params.tourismName}


        AND ALG_NAME = #{params.algName}


        AND DENSITY >= #{params.minDensity}


        AND DENSITY <= #{params.maxDensity}


        AND RECORD_TIME >= #{params.startTime}


        AND RECORD_TIME <= #{params.endTime}

SELECT 
FROM CLOUDWALK.CROWD_STATISTICS
WHERE DEVICE_CODE = #{deviceCode}

    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY RECORD_TIME DESC

SELECT TO_CHAR(RECORD_TIME, 'HH24') AS hour, SUM(COUNT) AS total_count, COUNT(1) AS record_count, ROUND(AVG(COUNT), 2) AS avg_count, ROUND(AVG(DENSITY), 4) AS avg_density FROM CLOUDWALK.CROWD_STATISTICS WHERE 1=1
AND DEVICE_CODE = #{deviceCode}
AND TOURISM_NAME = #{tourismName}
AND RECORD_TIME >= #{startTime}
AND RECORD_TIME <= #{endTime}
GROUP BY TO_CHAR(RECORD_TIME, 'HH24') ORDER BY hour

SELECT CASE WHEN DENSITY <= 0.3 THEN '低密度' WHEN DENSITY <= 0.6 THEN '中密度' ELSE '高密度' END AS density_level, COUNT(1) AS count, ROUND(AVG(COUNT), 2) AS avg_count, ROUND(AVG(DENSITY), 4) AS avg_density FROM CLOUDWALK.CROWD_STATISTICS WHERE 1=1
AND DEVICE_CODE = #{deviceCode}
AND TOURISM_NAME = #{tourismName}
AND RECORD_TIME >= #{startTime}
AND RECORD_TIME <= #{endTime}
GROUP BY CASE WHEN DENSITY <= 0.3 THEN '低密度' WHEN DENSITY <= 0.6 THEN '中密度' ELSE '高密度' END ORDER BY avg_density

SELECT 
    TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24:MI:SS') AS time,
    SUM(COUNT) AS total_count,
    ROUND(AVG(DENSITY), 4) AS avg_density
FROM CLOUDWALK.CROWD_STATISTICS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY RECORD_TIME
ORDER BY RECORD_TIME

SELECT

FROM CROWD_STATISTICS
WHERE RECORD_TIME BETWEEN #{startTime} AND #{endTime}

    AND TOURISM_NAME = #{tourismName}

ORDER BY RECORD_TIME DESC

SELECT HOUR(record_time) as hour, COUNT(*) as count, AVG(density) as avg_density FROM CROWD_STATISTICS WHERE 1=1
AND device_code = #{deviceCode}
AND tourism_name = #{tourismName}
AND record_time BETWEEN #{startTime} AND #{endTime} GROUP BY HOUR(record_time) ORDER BY hour

SELECT CASE WHEN density >= 0.8 THEN '高密度' WHEN density >= 0.5 THEN '中密度' ELSE '低密度' END as density_level, COUNT(*) as count FROM CROWD_STATISTICS WHERE 1=1
AND device_code = #{deviceCode}
AND tourism_name = #{tourismName}
AND record_time BETWEEN #{startTime} AND #{endTime} GROUP BY CASE WHEN density >= 0.8 THEN '高密度' WHEN density >= 0.5 THEN '中密度' ELSE '低密度' END

SELECT DATE_FORMAT(record_time, '%Y-%m-%d %H:00:00') as time_point, AVG(density) as avg_density, MAX(density) as max_density, MIN(density) as min_density FROM CROWD_STATISTICS WHERE 1=1
AND device_code = #{deviceCode}
AND tourism_name = #{tourismName}
AND record_time BETWEEN #{startTime} AND #{endTime} GROUP BY DATE_FORMAT(record_time, '%Y-%m-%d %H:00:00') ORDER BY time_point

SELECT 
    device_code,
    tourism_name,
    MAX(density) as max_density,
    COUNT(*) as high_density_count,
    MAX(record_time) as latest_record_time
FROM CROWD_STATISTICS
WHERE density >= #{densityThreshold}

    AND device_code = #{deviceCode}


    AND tourism_name = #{tourismName}

AND record_time BETWEEN #{startTime} AND #{endTime}
GROUP BY device_code, tourism_name
ORDER BY max_density DESC

